node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return ""}}
const S=rd("test/e2e/surfaces.ts");if(!S)fail("test/e2e/surfaces.ts is gone")
const V=rd("test/e2e/visual.spec.ts");if(!V)fail("test/e2e/visual.spec.ts is gone")
if(!/\{ path: \x27\/admin\/qr\x27,/.test(S))fail("/admin/qr has left OPERATOR_PATHS. This row does NOT close by deleting the surface: a roster without it stops photographing it, which is the HYG-026 silence")
const a=S.indexOf("ADVISORY_OPERATOR_SURFACES: Readonly");if(a<0)fail("ADVISORY_OPERATOR_SURFACES is gone or unreadable, so this arm cannot measure anything")
const body=S.slice(a,S.indexOf("\n}",a)).replace(/^\s*\/\/.*$/gm,"")
if(/\x27\/admin\/qr\x27\s*:/.test(body))fail("/admin/qr is advisory again: photographed and not voting. Both of its readings are fixed at their cause (ADR-1568: the touch drop for the flip, the admin-rail mask for the desktop diff); read the runner message, which names the box that moved, before downgrading")
if(V.includes("!ADVISORY_OPERATOR_PATHS.includes(s.path)")||V.includes("visual · operator console · advisory"))fail("visual.spec.ts still carries the operator advisory wiring (the blocking-loop filter or the advisory describe). A surface out of the blocking loop by ANY marker is not voting, and this row does not close while that is true; visual-tiers.test.ts holds the wiring and the roster in step")
const v=/VIEWPORT_ONLY_OPERATOR_PATHS: readonly string\[\] = \[([^\]]*)\]/.exec(S)
if(!v)fail("VIEWPORT_ONLY_OPERATOR_PATHS is gone or no longer a literal array, so this arm cannot tell whether /admin/qr is photographed whole")
if(v[1].includes("/admin/qr"))fail("/admin/qr is photographing its first screen only again: that is the workaround, and the flip it worked around is fixed at its cause (the touch drop, LIVE-492)")
const goto=V.indexOf("await page.goto(surface.path");const drop=V.indexOf("await dropTouchBeforeFullPageCapture(page)");const settle=V.indexOf("const settleReport = await settle(page)")
if(drop<0||!(goto<drop&&drop<settle))fail("capture() no longer drops touch emulation between goto and settle(), so a full-page capture at 390 photographs the coarse layout first and the fine layout second: the 14521/14567 flip is back on this surface")
const rail=rd("components/frequency/admin/admin-nav.tsx")
if(!rail.includes("data-visual-mask=\"admin-rail\""))fail("the operator info rail lost data-visual-mask=\"admin-rail\": its live profiles count is the 951/1029 px desktop diff on this surface (and /admin/library reads the same 1029 px to the pixel), and without the box the surface reds on the next member join")
if(!S.includes("value: \x27admin-rail\x27"))fail("VISUAL_MASK_SITES no longer registers admin-rail, so the reason for the mask is not written beside the selector that applies it")
const chart=rd("app/(main)/admin/qr/analytics.tsx")
if((chart.match(/data-visual-mask="qr-daily-scans"/g)||[]).length<2)fail("the scans section no longer masks BOTH branches (chart and empty state) as qr-daily-scans: when the 30-day window empties, the masked box swaps for unmasked text under the full-page camera and the surface reds on whichever pull request runs next")
const D="test/e2e/__screenshots__/visual.spec.ts/"
const h=(n)=>fs.readFileSync(D+n).readUInt32BE(20)
let ctl;try{ctl=h("about--dawn-light-desktop.png")}catch(e){fail("POSITIVE CONTROL FAILED: cannot read a known full-page baseline, so the height reader proves nothing")}
if(ctl<=800)fail("POSITIVE CONTROL FAILED: a full-page baseline reads "+ctl+"px, not taller than a viewport, so this probe cannot tell first-screen from whole-page")
const want={desktop:800,mobile:844};const bad=[]
for(const t of ["light","dark"])for(const k of Object.keys(want)){const n="admin-qr--dawn-"+t+"-"+k+".png";let got;try{got=h(n)}catch(e){bad.push(n+" is missing");continue}if(got<=want[k])bad.push(n+" is "+got+"px, one viewport")}
if(bad.length)fail("the /admin/qr baselines are still first-screen pictures, so the ~13,700px below the fold are not under the camera: "+bad.join("; ")+". Recapture on the runner (e2e-manual update_baselines + capture_shell against the branch preview) with the touch drop in place")
process.exit(0)'
